const payload = $input.item.json.body || {};
const lojaId = payload.loja_id ? parseInt(payload.loja_id, 10) : null;
const search = (payload.search || '').trim();
const origem = (payload.origem && payload.origem !== 'todos') ? payload.origem.trim() : '';
const allowedQuickFilters = ['todos', 'sem_resposta', 'sla_estourado', 'meta_ads', 'google_ads'];
const quickFilter = allowedQuickFilters.includes(payload.quick_filter) ? payload.quick_filter : 'todos';
const rawLimit = parseInt(payload.limit || '50', 10);
const limit = Number.isFinite(rawLimit) ? Math.min(Math.max(rawLimit, 1), 200) : 50;
const rawOffset = parseInt(payload.offset || '0', 10);
const offset = Number.isFinite(rawOffset) ? Math.max(rawOffset, 0) : 0;
const allowedSorts = ['nome', 'loja_nome', 'origem', 'last_message_at', 'total_mensagens', 'tempo_medio_resposta_segundos'];
const sortBy = allowedSorts.includes(payload.sort_by) ? payload.sort_by : 'last_message_at';
const sortDir = payload.sort_dir === 'asc' ? 'asc' : 'desc';

return {
  json: {
    lojaId,
    search,
    origem,
    quickFilter,
    limit,
    offset,
    sortBy,
    sortDir
  }
};

const first = $input.first()?.json || {};
const data = first.data || {};

return {
  json: {
    ok: true,
    contatos: data.contatos || [],
    resumo: data.resumo || {
      total_contatos: 0,
      leads_ads: 0,
      sem_resposta: 0,
      sla_estourado: 0,
      total_filtrado: 0
    }
  }
};
